class ExecutionScenario:
    def __init__(self, job_set):
        self.job_release_times = {}
        self.segment_execution_times = {}
        self.critical_section_lengths = {}

        for job_i in job_set:
            # Choose r_i within [r_min_i, r_max_i]
            self.job_release_times[job_i.id] = random.randint(job_i.r_min, job_i.r_max)
            for segment_j in job_i.segments:
                # Choose C_i_j within [C_min_i_j, C_max_i_j]
                self.segment_execution_times[(job_i.id, segment_j.id)] = random.randint(segment_j.C_min, segment_j.C_max)
                # Choose L_i_j within [L_min_i_j, L_max_i_j]
                self.critical_section_lengths[(job_i.id, segment_j.id)] = random.randint(segment_j.L_min, segment_j.L_max)

class SAG_State:
    def __init__(self, id, completed_segments_set, ...):
        self.id = id
        self.completed_segments_set = completed_segments_set
        # ... other state variables

# When merging states v_p and v_q into v_z:
# This property implies that if v_p and v_q are 'similar' and can be merged,
# they must represent the same set of completed segments.
# The merge operation ensures that the merged state v_z also reflects this set.

def merge_states(state_p, state_q):
    if state_p.completed_segments_set == state_q.completed_segments_set:
        # Create merged state v_z
        v_z = SAG_State(new_id, state_p.completed_segments_set, ...)
        return v_z
    else:
        raise Exception("States cannot be merged due to different completed segment sets")

class SystemState:
    def __init__(self, ...):
        self.claimed_cores_availability = {}
        # self.claimed_cores_availability maps job_id to [Cl_min, Cl_max]

    def get_claimed_core_availability(self, job_id):
        return self.claimed_cores_availability.get(job_id, [0, 0]) # Default to [0,0] if not claimed

class SystemState:
    def __init__(self, ...):
        self.free_cores_availability = [] # List of [A_min, A_max] intervals, sorted by A_min

    def get_free_core_availability(self, index):
        if 0 <= index < len(self.free_cores_availability):
            return self.free_cores_availability[index]
        else:
            return [float('inf'), float('inf')] # No such free core

class SystemState:
    def __init__(self, ...):
        self.resource_availability = {} # Maps resource_id to [SR_min, SR_max]

    def get_resource_availability(self, resource_id):
        return self.resource_availability.get(resource_id, [0, 0]) # Default to [0,0] if not tracked or always available

    def get_segment_resource_availability(self, segment_j):
        if segment_j.resources:
            resource_id = list(segment_j.resources)[0] # Assuming at most one resource
            return self.get_resource_availability(resource_id)
        else:
            return [0, 0]

def get_potentially_ready_segments(all_jobs, started_segments_on_path):
    R_P = set()
    for job_i in all_jobs:
        for j_idx, segment_j in enumerate(job_i.segments):
            segment_id = (job_i.id, segment_j.id)
            if segment_id not in started_segments_on_path:
                if j_idx == 0: # First segment of the job
                    R_P.add(segment_id)
                else:
                    prev_segment_id = (job_i.id, job_i.segments[j_idx-1].id)
                    if prev_segment_id in started_segments_on_path:
                        R_P.add(segment_id)
    return R_P

def calculate_EST(segment_j, job_i, state_p, m):
    if segment_j.is_first_segment():
        if state_p.num_claimed_cores() == m:
            return float('inf') # No free core
        else:
            # Max of earliest release, earliest free core, earliest resource availability
            return max(job_i.r_min, state_p.get_free_core_availability(0)[0], state_p.get_segment_resource_availability(segment_j)[0])
    else: # Not the first segment
        # Max of earliest claimed core availability, earliest resource availability
        return max(state_p.get_claimed_core_availability(job_i.id)[0], state_p.get_segment_resource_availability(segment_j)[0])

def calculate_EST_formula(job_id, segment_idx, state_p, m):
    if segment_idx == 1: # First segment
        if len(state_p.claimed_cores_availability) == m: # All cores claimed
            return float('inf')
        else:
            # Max of earliest release, earliest free core, earliest resource
            r_min_i = get_job_r_min(job_id)
            A_min_1_vp = state_p.free_cores_availability[0][0] if state_p.free_cores_availability else float('inf')
            SR_min_i_j_vp = state_p.get_segment_resource_availability(job_id, segment_idx)[0]
            return max(r_min_i, A_min_1_vp, SR_min_i_j_vp)
    else: # Not the first segment
        # Max of claimed core availability, earliest resource
        Cl_min_i_vp = state_p.claimed_cores_availability[job_id][0]
        SR_min_i_j_vp = state_p.get_segment_resource_availability(job_id, segment_idx)[0]
        return max(Cl_min_i_vp, SR_min_i_j_vp)

def calculate_ERT(segment_j, job_i, state_p):
    if segment_j.is_first_segment():
        # Max of earliest release, earliest free core availability
        return max(job_i.r_min, state_p.get_free_core_availability(0)[0])
    else: # Not the first segment
        # Earliest claimed core availability
        return state_p.get_claimed_core_availability(job_i.id)[0]

def calculate_tw(segment_z, job_y, state_p, m):
    if segment_z.is_first_segment():
        if state_p.num_claimed_cores() == m:
            return float('inf') # No free core
        else:
            # Max of latest release, latest free core, latest resource availability
            return max(job_y.r_max, state_p.get_free_core_availability(0)[1], state_p.get_segment_resource_availability(segment_z)[1])
    else: # Not the first segment
        # Max of latest claimed core availability, latest resource availability
        return max(state_p.get_claimed_core_availability(job_y.id)[1], state_p.get_segment_resource_availability(segment_z)[1])

def calculate_tw_formula(job_id, segment_idx, state_p, m):
    if segment_idx == 1: # First segment
        if len(state_p.claimed_cores_availability) == m: # All cores claimed
            return float('inf')
        else:
            # Max of latest release, latest free core, latest resource
            r_max_y = get_job_r_max(job_id)
            A_max_1_vp = state_p.free_cores_availability[0][1] if state_p.free_cores_availability else float('inf')
            SR_max_y_z_vp = state_p.get_segment_resource_availability(job_id, segment_idx)[1]
            return max(r_max_y, A_max_1_vp, SR_max_y_z_vp)
    else: # Not the first segment
        # Max of claimed core availability, latest resource
        Cl_max_y_vp = state_p.claimed_cores_availability[job_id][1]
        SR_max_y_z_vp = state_p.get_segment_resource_availability(job_id, segment_idx)[1]
        return max(Cl_max_y_vp, SR_max_y_z_vp)

def calculate_t_wc_formula(R_P, state_p, m):
    tw_values = []
    for job_id, segment_idx in R_P:
        tw_values.append(calculate_tw_formula(job_id, segment_idx, state_p, m))

    if not tw_values:
        return float('inf')
    else:
        return min(tw_values)

def calculate_th(segment_yz, job_y, segment_ij, job_i, state_p):
    # H = {J_y_z | J_y_z in R_P and priority(J_y_z) > priority(J_i_j) and no_resource_overlap(J_y_z, J_i_j)}
    if segment_yz.is_first_segment():
        if segment_ij.is_first_segment(): # Case 1: z=1, j=1
            return max(job_y.r_max, state_p.get_segment_resource_availability(segment_yz)[1])
        else: # Case 2: z=1, j>1
            return max(state_p.get_free_core_availability(0)[1], job_y.r_max, state_p.get_segment_resource_availability(segment_yz)[1])
    else: # Case 3: z>1
        return max(state_p.get_claimed_core_availability(job_y.id)[1], state_p.get_segment_resource_availability(segment_yz)[1])

def calculate_th_formula(job_y_id, segment_y_idx, job_i_id, segment_i_idx, state_p):
    r_max_y = get_job_r_max(job_y_id)
    SR_max_y_z_vp = state_p.get_segment_resource_availability(job_y_id, segment_y_idx)[1]

    if segment_y_idx == 1: # J_y_z is first segment
        if segment_i_idx == 1: # J_i_j is also first segment
            return max(r_max_y, SR_max_y_z_vp)
        else: # J_i_j is not first segment
            A_max_1_vp = state_p.free_cores_availability[0][1] if state_p.free_cores_availability else float('inf')
            return max(A_max_1_vp, r_max_y, SR_max_y_z_vp)
    else: # J_y_z is not first segment
        Cl_max_y_vp = state_p.claimed_cores_availability[job_y_id][1]
        return max(Cl_max_y_vp, SR_max_y_z_vp)

def calculate_t_high_formula(segment_ij, job_i, R_P, state_p):
    H = get_higher_priority_non_conflicting_segments(segment_ij, job_i, R_P)
    th_values = []
    for job_y_id, segment_y_idx in H:
        th_values.append(calculate_th_formula(job_y_id, segment_y_idx, job_i.id, segment_ij.id, state_p))

    if not th_values:
        return float('inf')
    else:
        return min(th_values)

def calculate_LST(segment_j, job_i, state_p, m):
    t_wc_val = calculate_t_wc(get_potentially_ready_segments(all_jobs, state_p.started_segments), state_p, m)
    t_high_val = calculate_t_high(segment_j, job_i, get_potentially_ready_segments(all_jobs, state_p.started_segments), state_p)
    return min(t_wc_val, t_high_val - 1)

def calculate_LRT(segment_z, job_y, state_p):
    if segment_z.is_first_segment():
        # Max of latest release, latest free core availability
        return max(job_y.r_max, state_p.get_free_core_availability(0)[1])
    else: # Not the first segment
        # Latest claimed core availability
        return state_p.get_claimed_core_availability(job_y.id)[1]

