def update_claimed_cores_lemma_10(state_p, segment_ij_starting_EST):
    new_claimed_cores_availability = {}
    for job_id, (cl_min, cl_max) in state_p.claimed_cores_availability.items():
        # If this is the job that just started, its interval is updated differently (by EFT/LFT of J_i_j)
        # This lemma applies to *other* claimed cores.
        new_cl_min = max(segment_ij_starting_EST, cl_min)
        new_cl_max = max(segment_ij_starting_EST, cl_max)
        new_claimed_cores_availability[job_id] = [new_cl_min, new_cl_max]
    return new_claimed_cores_availability
